/**
 * `SetMachine` rather than `Machine`: a Kotlin variant named after its field's type shadows that type.
 */
sealed class Command {
    
    data class Step(
        val `letter`: uniffi.oni_link_ffi.Letter, 
        val `by`: kotlin.Byte) : Command()
        
    {
        

        companion object
    }
    
    data class Reset(
        val `letter`: uniffi.oni_link_ffi.Letter) : Command()
        
    {
        

        companion object
    }
    
    data class StepEffect(
        val `effect`: uniffi.oni_link_ffi.Effect, 
        val `by`: kotlin.Byte) : Command()
        
    {
        

        companion object
    }
    
    data class ResetEffect(
        val `effect`: uniffi.oni_link_ffi.Effect) : Command()
        
    {
        

        companion object
    }
    
    data class SetMachine(
        val `machine`: uniffi.oni_link_ffi.Machine) : Command()
        
    {
        

        companion object
    }
    
    data class Walk(
        val `by`: kotlin.Byte) : Command()
        
    {
        

        companion object
    }
    
    object Undo : Command()
    
    
    object Redo : Command()
    
    
    data class SetFace(
        val `face`: uniffi.oni_link_ffi.Face) : Command()
        
    {
        

        companion object
    }
    
    /**
     * A panel slider moved by `by` hundredths of its track, as the desktop's arrow keys move it.
     */
    data class StepParam(
        val `param`: uniffi.oni_link_ffi.Param, 
        val `by`: kotlin.Byte) : Command()
        
    {
        

        companion object
    }
    
    /**
     * A panel slider back where a double click on the desktop returns it.
     */
    data class ResetParam(
        val `param`: uniffi.oni_link_ffi.Param) : Command()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCommand : FfiConverterRustBuffer<Command>{
    override fun read(buf: ByteBuffer): Command {
        return when(buf.getInt()) {
            1 -> Command.Step(
                FfiConverterTypeLetter.read(buf),
                FfiConverterByte.read(buf),
                )
            2 -> Command.Reset(
                FfiConverterTypeLetter.read(buf),
                )
            3 -> Command.StepEffect(
                FfiConverterTypeEffect.read(buf),
                FfiConverterByte.read(buf),
                )
            4 -> Command.ResetEffect(
                FfiConverterTypeEffect.read(buf),
                )
            5 -> Command.SetMachine(
                FfiConverterTypeMachine.read(buf),
                )
            6 -> Command.Walk(
                FfiConverterByte.read(buf),
                )
            7 -> Command.Undo
            8 -> Command.Redo
            9 -> Command.SetFace(
                FfiConverterTypeFace.read(buf),
                )
            10 -> Command.StepParam(
                FfiConverterTypeParam.read(buf),
                FfiConverterByte.read(buf),
                )
            11 -> Command.ResetParam(
                FfiConverterTypeParam.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Command): ULong = when(value) {
        is Command.Step -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeLetter.allocationSize(value.`letter`)
                + FfiConverterByte.allocationSize(value.`by`)
            )
        }
        is Command.Reset -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeLetter.allocationSize(value.`letter`)
            )
        }
        is Command.StepEffect -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeEffect.allocationSize(value.`effect`)
                + FfiConverterByte.allocationSize(value.`by`)
            )
        }
        is Command.ResetEffect -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeEffect.allocationSize(value.`effect`)
            )
        }
        is Command.SetMachine -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeMachine.allocationSize(value.`machine`)
            )
        }
        is Command.Walk -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByte.allocationSize(value.`by`)
            )
        }
        is Command.Undo -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Command.Redo -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Command.SetFace -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFace.allocationSize(value.`face`)
            )
        }
        is Command.StepParam -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeParam.allocationSize(value.`param`)
                + FfiConverterByte.allocationSize(value.`by`)
            )
        }
        is Command.ResetParam -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeParam.allocationSize(value.`param`)
            )
        }
    }

    override fun write(value: Command, buf: ByteBuffer) {
        when(value) {
            is Command.Step -> {
                buf.putInt(1)
                FfiConverterTypeLetter.write(value.`letter`, buf)
                FfiConverterByte.write(value.`by`, buf)
                Unit
            }
            is Command.Reset -> {
                buf.putInt(2)
                FfiConverterTypeLetter.write(value.`letter`, buf)
                Unit
            }
            is Command.StepEffect -> {
                buf.putInt(3)
                FfiConverterTypeEffect.write(value.`effect`, buf)
                FfiConverterByte.write(value.`by`, buf)
                Unit
            }
            is Command.ResetEffect -> {
                buf.putInt(4)
                FfiConverterTypeEffect.write(value.`effect`, buf)
                Unit
            }
            is Command.SetMachine -> {
                buf.putInt(5)
                FfiConverterTypeMachine.write(value.`machine`, buf)
                Unit
            }
            is Command.Walk -> {
                buf.putInt(6)
                FfiConverterByte.write(value.`by`, buf)
                Unit
            }
            is Command.Undo -> {
                buf.putInt(7)
                Unit
            }
            is Command.Redo -> {
                buf.putInt(8)
                Unit
            }
            is Command.SetFace -> {
                buf.putInt(9)
                FfiConverterTypeFace.write(value.`face`, buf)
                Unit
            }
            is Command.StepParam -> {
                buf.putInt(10)
                FfiConverterTypeParam.write(value.`param`, buf)
                FfiConverterByte.write(value.`by`, buf)
                Unit
            }
            is Command.ResetParam -> {
                buf.putInt(11)
                FfiConverterTypeParam.write(value.`param`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






