sealed class LinkException: kotlin.Exception() {
    
    class BadCode(
        
        val `what`: kotlin.String
        ) : LinkException() {
        override val message
            get() = "what=${ `what` }"
    }
    
    class Version(
        
        val `peer`: kotlin.UShort
        ) : LinkException() {
        override val message
            get() = "peer=${ `peer` }"
    }
    
    class Refused(
        ) : LinkException() {
        override val message
            get() = ""
    }
    
    class Unreachable(
        ) : LinkException() {
        override val message
            get() = ""
    }
    
    class ImportUnavailable(
        ) : LinkException() {
        override val message
            get() = ""
    }
    
    class ImportRefused(
        ) : LinkException() {
        override val message
            get() = ""
    }
    
    class Failed(
        
        val `reason`: kotlin.String
        ) : LinkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LinkException> {
        override fun lift(error_buf: RustBuffer.ByValue): LinkException = FfiConverterTypeLinkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkError : FfiConverterRustBuffer<LinkException> {
    override fun read(buf: ByteBuffer): LinkException {
        

        return when(buf.getInt()) {
            1 -> LinkException.BadCode(
                FfiConverterString.read(buf),
                )
            2 -> LinkException.Version(
                FfiConverterUShort.read(buf),
                )
            3 -> LinkException.Refused()
            4 -> LinkException.Unreachable()
            5 -> LinkException.ImportUnavailable()
            6 -> LinkException.ImportRefused()
            7 -> LinkException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LinkException): ULong {
        return when(value) {
            is LinkException.BadCode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`what`)
            )
            is LinkException.Version -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`peer`)
            )
            is LinkException.Refused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LinkException.Unreachable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LinkException.ImportUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LinkException.ImportRefused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LinkException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: LinkException, buf: ByteBuffer) {
        when(value) {
            is LinkException.BadCode -> {
                buf.putInt(1)
                FfiConverterString.write(value.`what`, buf)
                Unit
            }
            is LinkException.Version -> {
                buf.putInt(2)
                FfiConverterUShort.write(value.`peer`, buf)
                Unit
            }
            is LinkException.Refused -> {
                buf.putInt(3)
                Unit
            }
            is LinkException.Unreachable -> {
                buf.putInt(4)
                Unit
            }
            is LinkException.ImportUnavailable -> {
                buf.putInt(5)
                Unit
            }
            is LinkException.ImportRefused -> {
                buf.putInt(6)
                Unit
            }
            is LinkException.Failed -> {
                buf.putInt(7)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




